[{"order":1,"type":"heading","text":"Logging, Monitoring, and APM Integration in Express.js"},{"order":2,"type":"paragraph","text":"Observability is a cornerstone of modern production engineering. In an Express.js application, observability breaks down into three distinct pillars: structured logging, metrics collection (monitoring), and distributed tracing via Application Performance Monitoring (APM). Mastering these disciplines ensures rapid incident response, performance optimization, and reliable issue diagnosis."},{"order":3,"type":"subheading","text":"1. High-Performance Structured Logging with Pino"},{"order":4,"type":"paragraph","text":"Standard console.log statements are synchronous, unformatted, and degrade performance under heavy I/O load. Pino offers asynchronous, JSON-formatted output with minimal overhead. Paired with pino-http, it enables contextual HTTP logging automatically."},{"order":5,"type":"code","text":"const express = require('express');
const pino = require('pino');
const pinoHttp = require('pino-http');
const crypto = require('crypto');

const logger = pino({
  level: process.env.LOG_LEVEL || 'info',
  formatters: {
    level: (label) => ({ level: label.toUpperCase() })
  },
  timestamp: pino.stdTimeFunctions.isoTime
});

const app = express();

// Attach HTTP logger with unique request correlation IDs
app.use(
  pinoHttp({
    logger,
    genReqId: (req) => req.headers['x-request-id'] || crypto.randomUUID(),
    customLogLevel: (req, res, err) => {
      if (res.statusCode >= 500 || err) return 'error';
      if (res.statusCode >= 400) return 'warn';
      return 'info';
    }
  })
);

app.get('/api/users', (req, res) => {
  req.log.info({ userId: 42 }, 'Fetching user details');
  res.json({ id: 42, name: 'Alice' });
});"},{"order":6,"type":"bullet_point","text":"Structured JSON: Allows log aggregators like Datadog, ElasticSearch, or CloudWatch to index metadata attributes natively without regular expression parsing."},{"order":7,"type":"bullet_point","text":"Correlation ID (x-request-id): Attaches a unique identifier to every incoming request, enabling seamless tracking of execution flow across multiple microservices."},{"order":8,"type":"subheading","text":"2. Contextual Request Tracing using AsyncLocalStorage"},{"order":9,"type":"paragraph","text":"Node.js provides the AsyncLocalStorage API to preserve execution context across asynchronous boundaries without manually threading request objects through nested function calls."},{"order":10,"type":"code","text":"const { AsyncLocalStorage } = require('async_hooks');
const asyncLocalStorage = new AsyncLocalStorage();

// Context initialization middleware
app.use((req, res, next) => {
  const traceId = req.headers['x-request-id'] || crypto.randomUUID();
  const store = new Map();
  store.set('traceId', traceId);

  asyncLocalStorage.run(store, () => {
    next();
  });
});

// Global helper for nested services
function getTraceId() {
  const store = asyncLocalStorage.getStore();
  return store ? store.get('traceId') : null;
}"},{"order":11,"type":"subheading","text":"3. Exposing Metrics with Prometheus (prom-client)"},{"order":12,"type":"paragraph","text":"System health and runtime statistics are tracked by capturing counters, gauges, and histograms. The prom-client library provides default Node.js runtime metrics (heap usage, event loop lag) and custom HTTP duration tracking."},{"order":13,"type":"code","text":"const client = require('prom-client');

// Collect standard Node.js runtime metrics
const collectDefaultMetrics = client.collectDefaultMetrics;
collectDefaultMetrics({ register: client.register });

// Custom Histogram to measure HTTP request duration
const httpRequestDurationMicroseconds = new client.Histogram({
  name: 'http_request_duration_seconds',
  help: 'Duration of HTTP requests in seconds',
  labelNames: ['method', 'route', 'status_code'],
  buckets: [0.05, 0.1, 0.3, 0.5, 1, 2, 5]
});

// Interceptor middleware for metrics
app.use((req, res, next) => {
  const start = process.hrtime();
  res.on('finish', () => {
    const [seconds, nanoseconds] = process.hrtime(start);
    const duration = seconds + nanoseconds / 1e9;
    const route = req.route ? req.route.path : req.path;
    httpRequestDurationMicroseconds
      .labels(req.method, route, res.statusCode)
      .observe(duration);
  });
  next();
});

// Metrics endpoint for Prometheus scraping
app.get('/metrics', async (req, res) => {
  res.set('Content-Type', client.register.contentType);
  res.end(await client.register.metrics());
});"},{"order":14,"type":"subheading","text":"4. OpenTelemetry & APM Integration"},{"order":15,"type":"paragraph","text":"Application Performance Monitoring (APM) tools (such as New Relic, Datadog, or Elastic APM) capture distributed traces across network boundaries. OpenTelemetry (OTel) provides a vendor-neutral standard for instrumentation. The tracing initialization must run before importing Express."},{"order":16,"type":"code","text":"// tracer.js - Must be executed before any other module imports
const { NodeSDK } = require('@opentelemetry/sdk-node');
const { getNodeAutoInstrumentations } = require('@opentelemetry/auto-instrumentations-node');
const { OTLPTraceExporter } = require('@opentelemetry/exporter-trace-otlp-http');

const sdk = new NodeSDK({
  traceExporter: new OTLPTraceExporter({
    url: process.env.OTEL_EXPORTER_OTLP_ENDPOINT || 'http://localhost:4318/v1/traces'
  }),
  instrumentations: [getNodeAutoInstrumentations()]
});

sdk.start();

process.on('SIGTERM', () => {
  sdk.shutdown()
    .then(() => console.log('Tracing terminated'))
    .catch((error) => console.error('Error terminating tracing', error))
    .finally(() => process.exit(0));
});"},{"order":17,"type":"paragraph","text":"Start the Express application by loading the tracing configuration via Node CLI flag to guarantee instrumentation covers all libraries: 'node --require ./tracer.js server.js'."},{"order":18,"type":"subheading","text":"5. Error Capture and Observability Best Practices"},{"order":19,"type":"bullet_point","text":"Redact Sensitive Data: Ensure passwords, authorization tokens, and personal identifiable information (PII) are scrubbed before writing to logs."},{"order":20,"type":"bullet_point","text":"Separate Diagnostic Endpoints: Host the /metrics and /health endpoints on a dedicated internal port or protect them with reverse proxy rules to avoid exposing internal topology."},{"order":21,"type":"bullet_point","text":"Standardized Error Handling: Ensure custom error middleware records the full stack trace, correlated trace ID, and failure labels prior to returning a sanitized response to the client."}]
